import {WEAPONS,MONSTERS,ITEMS,getWeapon} from './content.js';
import {createSave,parseSave,stats,recipe,upgrade,rewardHunt} from './model.js';
import {Battle} from './engine.js';
import {renderScene,renderBattle,portrait,hunter} from './art.js';
const $=s=>document.querySelector(s),main=$('#main'),modal=$('#modal'),KEY='kamura-pixel-save-v1';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let save=null,selected=0,view='quests',battle=null,paused=false,settled=false,keys={},pendingStart=false,sound=false,audio=null,toastTimer,saveBroken=false;
try{const raw=localStorage.getItem(KEY);if(raw)save=parseSave(raw);}catch{saveBroken=true;setTimeout(()=>toast('原存档无法读取，已保留原数据。可导入备份恢复。'),500);}
const current=()=>save||createSave('新手猎人','female');
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function persist(){if(!save)return;try{if(saveBroken){const raw=localStorage.getItem(KEY);if(raw)localStorage.setItem(KEY+'-recovery',raw);saveBroken=false;}localStorage.setItem(KEY,JSON.stringify(save));$('#save-status').textContent='进度已保存到当前浏览器';}catch{$('#save-status').textContent='未能自动保存，请导出备份';toast('浏览器阻止了存档写入，请导出存档备份。');}header();}
function header(){$('#money').textContent=(save?.money||0).toLocaleString();$('#hunter-name').textContent=save?.name||'创建猎人';}
function showModal(html){$('#modal-body').innerHTML=html;if(!modal.open)modal.showModal();keys={};}
function closeModal(){modal.close();pendingStart=false;}
$('.modal-close').onclick=closeModal;modal.addEventListener('cancel',()=>{pendingStart=false;});
function profile(start=false){pendingStart=start;let gender=save?.gender||'female';showModal(`<div class="eyebrow">YOUR STORY BEGINS</div><h2 class="modal-title">成为神火村的猎人</h2><p class="modal-desc">给这段猎途一个名字。男女猎人拥有相同能力，选择你喜欢的样子。</p><label class="field-label" for="hunter-input">猎人姓名</label><input id="hunter-input" class="name-input" maxlength="24" autocomplete="off" placeholder="输入你的名字" value="${esc(save?.name||'')}"><span class="field-label">角色外观</span><div class="gender-options"><button class="gender-option ${gender==='male'?'selected':''}" data-gender="male">♂ 男猎人</button><button class="gender-option ${gender==='female'?'selected':''}" data-gender="female">♀ 女猎人</button></div><p id="form-error" class="error" role="alert"></p><button id="save-hunter" class="primary full">${save?'保存猎人资料':'准备好，开始猎途'} →</button>`);
 modal.querySelectorAll('[data-gender]').forEach(b=>b.onclick=()=>{gender=b.dataset.gender;modal.querySelectorAll('[data-gender]').forEach(x=>x.classList.toggle('selected',x===b));});
 $('#save-hunter').onclick=()=>{try{const identity=createSave($('#hunter-input').value,gender);if(save){save.name=identity.name;save.gender=gender;}else save=identity;persist();const startAfter=pendingStart;closeModal();if(startAfter)startHunt();else render();}catch(e){$('#form-error').textContent=e.message;}};
 $('#hunter-input').onkeydown=e=>{if(e.key==='Enter')$('#save-hunter').click();};$('#hunter-input').focus();}
$('#profile').onclick=()=>{if(battle){toast('返回营地后可以编辑猎人资料');return;}profile();};
function top(title,en,sub,tag='KAMURA VILLAGE'){return `<div class="section-top"><div><div class="eyebrow">${en}</div><h1>${title}</h1><p>${sub}</p></div><span class="tag">${tag}</span></div>`;}
function render(){header();$('#crumb').textContent={quests:'任务板',weapons:'装备箱',forge:'锻造铺',bag:'素材背包'}[view];document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='quests')renderQuests();if(view==='weapons')renderWeapons();if(view==='forge')renderForge();if(view==='bag')renderBag();}
function renderQuests(){const s=current(),m=MONSTERS[selected];main.innerHTML=top('猎人的新一天','THE HUNTER’S JOURNAL','整备行装，接下委托。山野中，还有新的故事。')+`<section class="hero" aria-label="像素废神社狩猎场景"><canvas id="camp-scene" width="1100" height="420"></canvas><div class="hero-copy"><div class="eyebrow">一 刀 一 猎 · 一 步 一 程</div><h2>下一场狩猎，<br>从这里开始。</h2><p>循着山风，走进未知的荒野。<br>让每一次凯旋，成为下一次出发的底气。</p></div><div class="hero-location">⌖ ${m.areaEn}</div><div class="hero-bottom">神火村 · 猎人集会所</div></section><div class="subheading"><h2>承接任务 <small>AVAILABLE QUESTS</small></h2><span>${Math.min(3,s.unlocked+1)} / 3 委托已开放</span></div><div class="quest-grid">${MONSTERS.map((m,i)=>`<button class="quest ${i===selected?'selected':''} ${i>s.unlocked?'locked':''}" data-quest="${i}" aria-label="${m.quest}，讨伐${m.name}${i>s.unlocked?'，尚未解锁':''}" aria-pressed="${i===selected}"><div class="quest-art"><span class="quest-num">QUEST 0${i+1}</span><span class="quest-status">${i>s.unlocked?'◇ 尚未解锁':s.wins[i]?'✓ 已完成':'可承接'}</span><canvas width="300" height="180" data-monster="${m.id}"></canvas></div><div class="quest-info"><div class="stars">${'★'.repeat(m.stars)}${'☆'.repeat(3-m.stars)}</div><h3>${m.name}</h3><div class="quest-en">${m.en}</div><div class="quest-meta"><span>⌖ ${m.area}</span><b>报酬 ${m.reward} z</b></div></div></button>`).join('')}</div><div class="departure"><div class="selected-icon">⚔</div><div><strong>${m.quest}</strong><p>讨伐 1 只${m.name} · 时限 5 分钟 · ${getWeapon(s.weapon).name} Lv.${s.levels[s.weapon]}</p></div><button id="depart" class="primary">出发狩猎<span>→</span></button></div><p class="keyboard-hint"><kbd>A</kbd><kbd>D</kbd> 移动 <span class="separator">/</span><kbd>SPACE</kbd> 跳跃 <span class="separator">/</span><kbd>J</kbd> 攻击 <span class="separator">/</span> 支持键盘与触屏操作</p>`;
 main.querySelectorAll('[data-monster]').forEach(c=>portrait(c,c.dataset.monster));main.querySelectorAll('[data-quest]').forEach(b=>b.onclick=()=>{const i=+b.dataset.quest;if(i>s.unlocked){toast('先完成「'+MONSTERS[i-1].quest+'」即可解锁');return;}selected=i;renderQuests();});$('#depart').onclick=()=>save?startHunt():profile(true);}
function renderWeapons(){const s=current(),w=getWeapon(s.weapon);main.innerHTML=top('让武器，回应你的风格','THE ARMORY','十四类武器，一个属于你的狩猎节奏。')+`<div class="weapon-detail"><h3>${w.name} <small>Lv.${s.levels[w.id]}</small></h3><div>当前攻击 ${stats(s).attack} · ${w.ranged?'远程弹体':'近战'} · 普攻间隔 ${w.speed}s</div><div><kbd>K</kbd> ${w.skills[0]} · 5 秒冷却　<kbd>L</kbd> ${w.skills[1]} · 9 秒冷却　<kbd>U</kbd> ${w.skills[2]} · 100 气势</div></div><div class="weapon-grid">${WEAPONS.map(w=>`<button class="weapon-card ${s.weapon===w.id?'selected':''}" data-weapon="${w.id}" aria-pressed="${s.weapon===w.id}"><span class="weapon-symbol">${w.icon}</span><b>${w.name} ${s.weapon===w.id?'✓':''}</b><small>${w.en}</small><div class="stats">Lv.${s.levels[w.id]} <span style="float:right">${w.ranged?'远程':'近战'} · ${w.attack} 基础攻击</span></div></button>`).join('')}</div>`;main.querySelectorAll('[data-weapon]').forEach(b=>b.onclick=()=>{if(!save){profile();return;}save.weapon=b.dataset.weapon;persist();renderWeapons();toast('已装备'+getWeapon(save.weapon).name);});}
function renderForge(){const s=current();main.innerHTML=top('把收获，锻造成力量','THE SMITHY','带上狩猎所得，让熟悉的武器更进一步。')+`<div class="forge-grid">${['weapon','armor'].map(type=>{const r=recipe(s,type),max=r.level>=5,can=!max&&s.money>=r.money&&Object.entries(r.items).every(([k,n])=>s.items[k]>=n);return `<section class="forge-card"><span class="weapon-symbol">${type==='weapon'?getWeapon(s.weapon).icon:'◈'}</span><div class="level">${type==='weapon'?'WEAPON':'ARMOR'} · LEVEL ${r.level} / 5</div><h2>${type==='weapon'?getWeapon(s.weapon).name:'神火猎人护甲'}</h2><p>${type==='weapon'?`当前攻击 ${stats(s).attack} · 下一级增加 22% 基础攻击`:`最大生命 ${stats(s).hp} · 防御 ${stats(s).defense} · 下一级 +20 生命 / +2 防御`}</p>${max?'<div class="weapon-detail">已到达当前版本最高等级</div>':Object.entries(r.items).map(([k,n])=>`<div class="cost"><span>${ITEMS[k].name}</span><span class="${s.items[k]<n?'short':''}">${s.items[k]} / ${n}</span></div>`).join('')+`<div class="cost"><span>锻造费用</span><span class="${s.money<r.money?'short':''}">${s.money} / ${r.money} z</span></div>`}<button class="primary" data-upgrade="${type}" ${!can?'disabled':''}>${max?'最高等级':can?'强化装备 →':'素材或金钱不足'}</button></section>`;}).join('')}</div><p class="intro">普通素材每次讨伐必得；稀有素材有 35% 概率获得。武器等级独立保存，护甲对所有武器生效。</p>`;main.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{if(!save)return;const result=upgrade(save,b.dataset.upgrade);if(result.ok){persist();renderForge();toast('强化成功，下一场狩猎会更从容。');}else toast(result.reason);});}
function renderBag(){const s=current();main.innerHTML=top('每份素材，都有来处','HUNTER’S COLLECTION','从荒野带回的战利品，也是下一把武器的起点。')+`<div class="inventory">${Object.entries(ITEMS).map(([k,v])=>`<article class="item ${v.rare?'rare':''}"><span class="count">× ${s.items[k]}</span><span class="item-symbol">${v.icon}</span><h3>${v.name}</h3><small>${v.rare?'稀有素材 · 35% 概率':'普通素材 · 讨伐必得'}</small></article>`).join('')}</div><div class="weapon-detail">狩猎记录　${MONSTERS.map((m,i)=>`${m.name} × ${s.wins[i]}`).join('　/　')}</div><p class="intro">存档保存在当前浏览器。更换设备前，请使用下方按钮导出备份。</p><button class="secondary" id="bag-export">↓ 导出存档</button> <button class="secondary" id="bag-import">↑ 导入存档</button>`;$('#bag-export').onclick=exportSave;$('#bag-import').onclick=()=>$('#import-file').click();}
function navigate(next){settleOutcome();if(battle&&battle.status==='playing'){pause(true);showModal(`<div class="eyebrow">RETURN TO CAMP</div><h2 class="modal-title">结束这次狩猎？</h2><p class="modal-desc">本次未完成的任务不会获得报酬，已保存的装备与素材不受影响。</p><div class="result-buttons"><button id="stay" class="secondary">继续狩猎</button><button id="leave" class="primary">返回营地</button></div>`);$('#stay').onclick=()=>{closeModal();pause(false);};$('#leave').onclick=()=>{closeModal();battle=null;keys={};view=next;render();};return;}battle=null;keys={};view=next;render();}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>navigate(b.dataset.view));
function control(action,label,key,cls=''){return `<button class="ctrl ${cls}" data-action="${action}" aria-label="${label}">${label}<small>${key}</small><span class="cd" id="cd-${action}"></span></button>`;}
function startHunt(){if(!save||selected>save.unlocked)return;battle=new Battle(save,selected);paused=false;settled=false;keys={};$('#crumb').textContent='狩猎中';const w=battle.w,m=battle.spec;main.innerHTML=`<div class="battle-top"><div><div class="eyebrow">QUEST 0${selected+1} · ${'★'.repeat(m.stars)}</div><h1>${m.quest}</h1><small>⌖ ${m.area} / ${m.areaEn}</small></div><div class="battle-actions"><button id="pause" class="secondary">Ⅱ 暂停</button><button id="return" class="secondary">返回营地</button></div></div><div class="arena"><canvas id="arena" width="960" height="440" aria-label="横版狩猎战斗，使用下方按钮或键盘操控猎人"></canvas><div class="hud"><div class="player-hud"><div class="hud-label">${esc(save.name)} · ${w.name}</div><div class="bar"><i id="hp-bar"></i></div><div class="bar stamina"><i id="stamina-bar"></i></div><small id="hp-label"></small></div><div class="timer" id="timer">05:00</div><div class="monster-hud"><div class="hud-label" id="monster-label">${m.name}</div><div class="bar monster-bar"><i id="monster-hp"></i></div><small id="monster-health"></small></div></div><div class="battle-caption"><span>← → 移动接近目标 · 观察攻击预警</span><span id="meter-label">气势 0 / 100</span></div><div class="paused-badge" id="paused" hidden>狩猎暂停</div></div><div class="control-deck"><div class="movement">${control('left','◀','A / ←')}${control('right','▶','D / →')}${control('jump','跳跃','SPACE')}${control('dodge','闪避','SHIFT')}${control('heal','回复药','H · 3')}</div><div class="skills">${control('attack','攻击','J','attack')}${control('skill1',w.skills[0],'K')}${control('skill2',w.skills[1],'L')}${control('ult',w.skills[2],'U','ultimate')}</div></div><p class="battle-help">近身后面向怪物出刀。命中积累气势，蓄满后释放终极技。技能按钮显示剩余冷却。</p><div class="battle-tip"><b>猎人笔记</b><br>${m.description} 橙色预警出现时，跳跃或闪避；怪物收招时是进攻的好机会。</div>`;
 $('#pause').onclick=()=>pause(!paused);$('#return').onclick=()=>navigate('quests');
 main.querySelectorAll('[data-action]').forEach(btn=>{btn.onpointerdown=e=>{e.preventDefault();if(paused||battle?.status!=='playing')return;btn.setPointerCapture(e.pointerId);btn.classList.add('pressed');const a=btn.dataset.action;if(['left','right','attack'].includes(a))keys[a]=true;else battle.request(a);};const release=()=>{keys[btn.dataset.action]=false;btn.classList.remove('pressed');};btn.onpointerup=release;btn.onpointercancel=release;btn.onlostpointercapture=release;});updateHud();}
function pause(value){if(!battle||battle.status!=='playing')return;paused=value;keys={};$('#paused').hidden=!value;$('#pause').textContent=value?'▶ 继续':'Ⅱ 暂停';}
function updateHud(){if(!battle||!$('#hp-bar'))return;const p=battle.p,m=battle.m;$('#hp-bar').style.width=p.hp/p.maxHp*100+'%';$('#stamina-bar').style.width=p.stamina+'%';$('#monster-hp').style.width=m.hp/m.maxHp*100+'%';$('#hp-label').textContent=`HP ${Math.ceil(p.hp)} / ${p.maxHp} · 耐力 ${Math.floor(p.stamina)}`;$('#monster-health').textContent=`${Math.ceil(m.hp)} / ${m.maxHp} HP`;$('#monster-label').textContent=battle.spec.name+(m.enraged?' · 愤怒':'');$('#meter-label').textContent=`气势 ${Math.floor(p.meter)} / 100`;$('#timer').textContent=String(Math.floor(battle.time/60)).padStart(2,'0')+':'+String(Math.floor(battle.time%60)).padStart(2,'0');$('#cd-skill1').textContent=p.c1>0?Math.ceil(p.c1):'';$('#cd-skill2').textContent=p.c2>0?Math.ceil(p.c2):'';$('#cd-ult').textContent=p.meter<100?`${Math.floor(p.meter)}%`:'';main.querySelector('[data-action="heal"] small').textContent=`H · ${p.potions}`;}
function settleOutcome(){if(!battle||battle.status==='playing'||battle.rewardApplied)return;battle.rewardApplied=true;battle.reward=battle.status==='won'?rewardHunt(save,selected,battle.id):null;if(battle.reward)persist();}
function finish(){settleOutcome();if(settled)return;settled=true;keys={};const won=battle.status==='won',reward=battle.reward;showModal(`<div class="eyebrow" style="text-align:center">${won?'QUEST COMPLETE':'QUEST FAILED'}</div><div class="result-seal">${won?'✧':'◇'}</div><h2 class="modal-title" style="text-align:center">${won?'狩猎成功':'整备之后，再次出发'}</h2><p class="modal-desc" style="text-align:center">${won?`成功讨伐${battle.spec.name} · 用时 ${Math.floor(300-battle.time)} 秒`:'本次未获得素材与报酬。利用闪避和回复药，寻找怪物收招的时机。'}</p><div class="result-drops">${reward?Object.entries(reward.drops).map(([k,v])=>`<div><span>${ITEMS[k].icon} ${ITEMS[k].name}</span><b>× ${v}</b></div>`).join('')+`<div><span>任务报酬</span><b>+ ${reward.money} z</b></div>`:''}</div><div class="result-buttons"><button id="again" class="secondary">再次挑战</button><button id="back" class="primary">${won?'回村锻造':'返回营地'} →</button></div>`);$('#again').onclick=()=>{closeModal();startHunt();};$('#back').onclick=()=>{closeModal();battle=null;view=won?'forge':'quests';render();};}
const mapping={KeyA:'left',ArrowLeft:'left',KeyD:'right',ArrowRight:'right',Space:'jump',KeyW:'jump',ArrowUp:'jump',KeyJ:'attack',KeyK:'skill1',KeyL:'skill2',KeyU:'ult',ShiftLeft:'dodge',ShiftRight:'dodge',KeyH:'heal'};
addEventListener('keydown',e=>{if(!battle||modal.open||/INPUT|TEXTAREA/.test(document.activeElement.tagName))return;if(e.code==='Escape'){e.preventDefault();if(!e.repeat)pause(!paused);return;}const a=mapping[e.code];if(!a)return;e.preventDefault();if(paused)return;if(['left','right','attack'].includes(a))keys[a]=true;else if(!e.repeat)battle.request(a);});
addEventListener('keyup',e=>{const a=mapping[e.code];if(a)keys[a]=false;});addEventListener('blur',()=>{keys={};pause(true);});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys={};pause(true);}});
function exportSave(){if(!save){toast('请先创建猎人');return;}const blob=new Blob([JSON.stringify(save,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='kamura-hunter-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#backup').onclick=exportSave;$('#restore').onclick=()=>{if(battle){toast('请先返回营地再导入存档');return;}$('#import-file').click();};
$('#import-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(battle){toast('请先返回营地');return;}try{if(file.size>100000)throw Error('文件过大，请选择游戏导出的 JSON 存档');const imported=parseSave(await file.text());showModal(`<div class="eyebrow">RESTORE SAVE</div><h2 class="modal-title">恢复猎人存档</h2><p class="modal-desc">将使用「${esc(imported.name)}」的存档替换当前进度。建议先导出当前存档。</p><button id="import-confirm" class="primary full">确认恢复</button>`);$('#import-confirm').onclick=()=>{save=imported;selected=0;persist();closeModal();render();toast('存档恢复成功');};}catch(e){toast(e.message||'无法读取存档');}};
$('#guide').onclick=()=>{if(battle)pause(true);showModal(`<div class="eyebrow">HUNTER’S FIELD GUIDE</div><h2 class="modal-title">狩猎手册</h2><p class="modal-desc">接取任务 → 讨伐怪物 → 收集素材 → 强化装备。击败前一只怪物即可解锁下一张委托。</p>${[['移动','A / D 或 ← / →'],['跳跃','空格 / W / ↑'],['普通攻击','J · 可按住连击'],['技能一 / 技能二','K / L'],['终极技','U · 气势达到 100'],['闪避','Shift · 消耗 25 耐力'],['回复药','H · 每场 3 瓶'],['暂停 / 继续','Esc']].map(([a,b])=>`<div class="guide-row"><span>${a}</span><span>${b}</span></div>`).join('')}<p class="modal-desc">攻击有距离与朝向限制。橙色区域是怪物攻击预警，跳跃或闪避可以规避攻击。触屏使用战斗画面下方的同名按钮，可同时按住移动和攻击。<br><br>本作是《怪物猎人》非官方像素同人原型，技能与数值经过独立简化。</p>`);};
$('#sound').onclick=()=>{sound=!sound;$('#sound').style.background=sound?'#dfe7d1':'transparent';$('#sound').setAttribute('aria-label',sound?'关闭声音':'开启声音');if(sound){audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();}toast(sound?'狩猎音效已开启':'狩猎音效已关闭');};
function beep(kind){if(!sound||!audio)return;const frequencies={hit:330,hurt:90,attack:180,skill1:460,skill2:550,ult:740,won:880};if(!frequencies[kind])return;const o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.setValueAtTime(frequencies[kind],audio.currentTime);o.frequency.exponentialRampToValueAtTime(frequencies[kind]/2,audio.currentTime+.12);g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.15);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.16);}
let last=0,acc=0,ui=0;function frame(now){const dt=Math.min(.05,(now-last)/1000||0);last=now;if(battle){if(!paused&&!modal.open){acc+=dt;while(acc>=1/60){battle.step(1/60,keys);acc-=1/60;}}else acc=0;settleOutcome();const canvas=$('#arena');if(canvas)renderBattle(canvas,battle);ui+=dt;if(ui>.06){updateHud();ui=0;}for(const e of battle.events.splice(0))beep(e.kind);if(battle.status!=='playing'&&battle.endAge>=.8&&!settled)finish();}else{acc=0;const canvas=$('#camp-scene');if(canvas)renderScene(canvas,selected,now/1000,save);}requestAnimationFrame(frame);}render();requestAnimationFrame(frame);
